pragma solidity ^0.8.24;

import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/* Minimální pohled do hlavního kontraktu kolekce */
interface IBiggiEyesMainView {
    function exists(uint256 tokenId) external view returns (bool);

    // true pokud owner vlastní všech 10 mainId v daném bloku
    function hasAllTenMainIdsInBlock(address owner, uint16 blk) external view returns (bool);

    // true pokud owner vlastní všechny background varianty pro konkrétní mainId v daném bloku
    function hasAllBackgroundsForMainIdInBlock(address owner, uint16 blk, uint256 mainId) external view returns (bool);
}

/* =============================================================================
 * BiggiCollectionRewards — pool v nativní měně pro odměny v rámci kolekce.
 * Distributor posílá část mintu do tohoto kontraktu.
 * =============================================================================*/
contract BiggiCollectionRewards is ReentrancyGuard {
    error NotEnoughBalance();
    error AlreadyClaimed();
    error InvalidIndex();
    error PaymentFailed();
    error OnlyOwner();
    error ZeroAddress();
    error NotDistributor();
    error AmountZero();
    error NotEligible();

    address public owner;
    IBiggiEyesMainView public main;

    address public distributor;

    // Částky (v wei, 1 ether == 1 POL dle chainu)
    uint256 public orangeReward  = 1000 ether;   // max 10x (mainId 1..10)
    uint256 public blockReward   = 3000 ether;   // max 9x (bloky 1..9)
    uint256 public rainbowReward = 10000 ether;  // globálně jednou

    // counters / limits
    uint8 public orangeWinnersCount; // max 10
    uint8 public blockWinnersCount;  // max 9
    bool  public rainbowRewardClaimedGlobal;

    // Tracking
    mapping(address => mapping(uint16 => bool)) public userClaimedBlock; // user -> blockIdx -> claimed
    mapping(uint256 => bool) public orangeMainIdPaid; // mainId (1..10) -> už jednou vyplaceno
    mapping(uint16 => bool)  public blockPaid;        // blockIdx -> už jednou vyplaceno

    event OrangeRewardClaimed(address indexed user, uint256 mainId, uint256 amount);
    event BlockRewardClaimed(address indexed user, uint16 blockIdx, uint256 amount);
    event RainbowRewardClaimed(address indexed user, uint256 amount);

    event DistributorSet(address indexed oldDistributor, address indexed newDistributor);
    event MintShareFromDistributor(uint256 amount);

    modifier onlyOwner() {
        if (msg.sender != owner) revert OnlyOwner();
        _;
    }

    constructor(address main_) {
        owner = msg.sender;
        if (main_ == address(0)) revert ZeroAddress();
        main = IBiggiEyesMainView(main_);
    }

    /* ===== admin ===== */
    function setOwner(address newOwner) external onlyOwner {
        if (newOwner == address(0)) revert ZeroAddress();
        owner = newOwner;
    }

    function setMain(address main_) external onlyOwner {
        if (main_ == address(0)) revert ZeroAddress();
        main = IBiggiEyesMainView(main_);
    }

    function setDistributor(address d) external onlyOwner {
        if (d == address(0)) revert ZeroAddress();
        emit DistributorSet(distributor, d);
        distributor = d;
    }

    function setRewardsAmounts(uint256 orange, uint256 blockAmt, uint256 rainbow) external onlyOwner {
        orangeReward = orange;
        blockReward = blockAmt;
        rainbowReward = rainbow;
    }

    /* ===== Claimy ===== */

    /// Orange reward:
    /// - Orange blok je blk=1
    /// - Uživatel musí vlastnit všechny background varianty pro dané mainId v oranžovém bloku
    /// - Každé mainId (1..10) může být odměněno jen jednou (orangeMainIdPaid)
    /// - Maximálně 10 výher celkem
    function claimOrangeReward(uint256 mainId) external nonReentrant {
        if (orangeReward == 0) revert InvalidIndex();
        if (orangeWinnersCount >= 10) revert AlreadyClaimed();
        if (mainId < 1 || mainId > 10) revert InvalidIndex();
        if (orangeMainIdPaid[mainId]) revert AlreadyClaimed();

        uint16 ORANGE_BLK = 1;

        bool ok = main.hasAllBackgroundsForMainIdInBlock(msg.sender, ORANGE_BLK, mainId);
        if (!ok) revert NotEligible();

        if (address(this).balance < orangeReward) revert NotEnoughBalance();

        orangeMainIdPaid[mainId] = true;
        unchecked { orangeWinnersCount++; }

        (bool sent, ) = msg.sender.call{value: orangeReward}("");
        if (!sent) revert PaymentFailed();

        emit OrangeRewardClaimed(msg.sender, mainId, orangeReward);
    }

    /// Block reward:
    /// - Bloky 1..9, pro každý blok pouze jednou globálně (blockPaid)
    /// - Uživateli bude vyplaceno pokud vlastní všech 10 mainId v daném bloku
    function claimBlockReward(uint16 blockIdx) external nonReentrant {
        if (blockReward == 0) revert InvalidIndex();
        if (blockWinnersCount >= 9) revert AlreadyClaimed();
        if (blockIdx < 1 || blockIdx > 9) revert InvalidIndex();
        if (blockPaid[blockIdx]) revert AlreadyClaimed();
        if (userClaimedBlock[msg.sender][blockIdx]) revert AlreadyClaimed();

        bool ok = main.hasAllTenMainIdsInBlock(msg.sender, blockIdx);
        if (!ok) revert NotEligible();

        if (address(this).balance < blockReward) revert NotEnoughBalance();

        blockPaid[blockIdx] = true;
        userClaimedBlock[msg.sender][blockIdx] = true;
        unchecked { blockWinnersCount++; }

        (bool sent, ) = msg.sender.call{value: blockReward}("");
        if (!sent) revert PaymentFailed();

        emit BlockRewardClaimed(msg.sender, blockIdx, blockReward);
    }

    /// Rainbow reward:
    /// - globálně jednou
    /// - vyžaduje vlastnit všech 10 mainId v bloku 10
    function claimRainbowReward() external nonReentrant {
        if (rainbowReward == 0) revert InvalidIndex();
        if (rainbowRewardClaimedGlobal) revert AlreadyClaimed();

        uint16 RAINBOW_BLK = 10;
        bool ok = main.hasAllTenMainIdsInBlock(msg.sender, RAINBOW_BLK);
        if (!ok) revert NotEligible();

        if (address(this).balance < rainbowReward) revert NotEnoughBalance();

        rainbowRewardClaimedGlobal = true;

        (bool sent, ) = msg.sender.call{value: rainbowReward}("");
        if (!sent) revert PaymentFailed();

        emit RainbowRewardClaimed(msg.sender, rainbowReward);
    }

    /* ===== Funding z Distributoru ===== */

    /// Distributor posílá native (POL) do kontraktu.
    function depositMintShareFromDistributor() external payable nonReentrant {
        if (msg.sender != distributor) revert NotDistributor();
        if (msg.value == 0) revert AmountZero();
        emit MintShareFromDistributor(msg.value);
    }

    /* Backward kompatibilita: starší jméno funkce */
    function receiveMintShare() external payable nonReentrant {
        if (msg.sender != distributor) revert NotDistributor();
        if (msg.value == 0) revert AmountZero();
        emit MintShareFromDistributor(msg.value);
    }

    receive() external payable {}

    /* ===== FE helpers (views) ===== */

    function canClaimOrange(address user, uint256 mainId) external view returns (bool ok, uint8 reason) {
        // reason:
        // 0=OK, 1=rewardOff, 2=limitReached, 3=badMainId, 4=alreadyPaidMainId, 5=notEligible, 6=insufficientBalance
        if (orangeReward == 0) return (false, 1);
        if (orangeWinnersCount >= 10) return (false, 2);
        if (mainId < 1 || mainId > 10) return (false, 3);
        if (orangeMainIdPaid[mainId]) return (false, 4);

        bool eligible = main.hasAllBackgroundsForMainIdInBlock(user, 1, mainId);
        if (!eligible) return (false, 5);

        if (address(this).balance < orangeReward) return (false, 6);
        return (true, 0);
    }

    function canClaimBlock(address user, uint16 blockIdx) external view returns (bool ok, uint8 reason) {
        // reason:
        // 0=OK, 1=rewardOff, 2=limitReached, 3=badBlock, 4=blockPaid, 5=userClaimed, 6=notEligible, 7=insufficientBalance
        if (blockReward == 0) return (false, 1);
        if (blockWinnersCount >= 9) return (false, 2);
        if (blockIdx < 1 || blockIdx > 9) return (false, 3);
        if (blockPaid[blockIdx]) return (false, 4);
        if (userClaimedBlock[user][blockIdx]) return (false, 5);

        bool eligible = main.hasAllTenMainIdsInBlock(user, blockIdx);
        if (!eligible) return (false, 6);

        if (address(this).balance < blockReward) return (false, 7);
        return (true, 0);
    }

    function canClaimRainbow(address user) external view returns (bool ok, uint8 reason) {
        // reason:
        // 0=OK, 1=rewardOff, 2=alreadyClaimedGlobal, 3=notEligible, 4=insufficientBalance
        if (rainbowReward == 0) return (false, 1);
        if (rainbowRewardClaimedGlobal) return (false, 2);

        bool eligible = main.hasAllTenMainIdsInBlock(user, 10);
        if (!eligible) return (false, 3);

        if (address(this).balance < rainbowReward) return (false, 4);
        return (true, 0);
    }

    function rewardsSnapshot(address user) external view returns (
        address owner_,
        address main_,
        address distributor_,
        uint256 contractBalance,
        uint256 orangeReward_,
        uint256 blockReward_,
        uint256 rainbowReward_,
        uint8 orangeWinners,
        uint8 blockWinners,
        bool rainbowClaimedGlobal,
        bool canRainbow,
        uint8 canRainbowReason
    ) {
        owner_ = owner;
        main_ = address(main);
        distributor_ = distributor;
        contractBalance = address(this).balance;

        orangeReward_ = orangeReward;
        blockReward_ = blockReward;
        rainbowReward_ = rainbowReward;

        orangeWinners = orangeWinnersCount;
        blockWinners = blockWinnersCount;
        rainbowClaimedGlobal = rainbowRewardClaimedGlobal;

        (canRainbow, canRainbowReason) = this.canClaimRainbow(user);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/**
 * BiggiCommunityCenter
 *
 * Owner-curated grants + events (bez hlasování).
 * - Pool (rezerva) v kontraktu: distributor posílá share (depositFromDistributor / receiveMintShare)
 * - Owner vytvoří event s meta (title, ipfsHash, start, end) + totalPrize
 * - Owner při vytvoření eventu přiřadí winners[] a amounts[] (per-winner amounts)
 *   -> součet amounts musí rovnat totalPrize
 * - Při vytvoření se totalPrize "zamkne" z poolBalance (rezervováno pro event)
 * - Výherci volají claim(eventId) a obdrží svůj přidělený amount
 * - Žádné refundy/cancel (NE)
 * - Owner nemá admin-override nad claim statusy (NE)
 *
 * Low-risk vylepšení:
 * - Zero-address guard u setDistributor
 * - vlastní Donation event (receive už nelže “OwnerDeposit”)
 * - zákaz duplicitních winner adres v jednom eventu (eliminuje tichou nekonzistenci)
 * - totalLocked tracking (emergencyWithdraw už nemusí loopovat všechny eventy)
 * - sjednocení revertů na custom errors tam, kde to dává smysl
 * - drobné FE helper views (canClaim + userStatus) bez změny logiky
 */

import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/Address.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract BiggiCommunityCenter is Ownable, ReentrancyGuard, Pausable {
    using Address for address payable;

    /* ------------ Events & Errors ------------ */
    event DistributorSet(address indexed oldDistributor, address indexed newDistributor);
    event DepositedFromDistributor(address indexed from, uint256 amount);
    event OwnerDeposit(address indexed from, uint256 amount);
    event DonationReceived(address indexed from, uint256 amount);

    event EventCreated(uint256 indexed eventId, string title, uint256 totalPrize);
    event WinnerAssigned(uint256 indexed eventId, address indexed winner, uint256 amount);
    event Claimed(uint256 indexed eventId, address indexed who, uint256 amount);

    event Rescue(address indexed to, uint256 amount);

    error NotDistributor();
    error ZeroAmount();
    error ZeroAddress();
    error BadLengths();
    error SumMismatch();
    error NotWinner();
    error AlreadyClaimed();
    error InsufficientPool();
    error EventNotExists();
    error DuplicateWinner();
    error TransferFailed();

    /* ------------ Storage ------------ */
    address public distributor; // distributor address (set by owner)

    uint256 public poolBalance; // POL available for new events (in wei)
    uint256 public totalLocked; // total locked across all events (avoids emergency loop)

    uint256 public nextEventId;

    struct EventInfo {
        string title;
        string ipfsHash;
        uint256 start;
        uint256 end;
        uint256 totalPrize; // requested total prize for event
        uint256 locked;     // how much currently locked / reserved for this event
        bool exists;
    }

    // eventId => EventInfo
    mapping(uint256 => EventInfo) public events;

    // eventId => winners array
    mapping(uint256 => address[]) private eventWinners;

    // eventId => winner => amount
    mapping(uint256 => mapping(address => uint256)) private eventAmounts;

    // eventId => winner => claimed
    mapping(uint256 => mapping(address => bool)) private eventClaimed;

    // list of all event ids
    uint256[] private allEventIds;

    /* ------------ Constructor ------------ */
    constructor(address initialOwner) Ownable(initialOwner) {
        nextEventId = 1;
    }

    /* ------------ Admin / Configuration ------------ */

    /// @notice set distributor address (owner)
    function setDistributor(address d) external onlyOwner {
        if (d == address(0)) revert ZeroAddress();
        address old = distributor;
        distributor = d;
        emit DistributorSet(old, d);
    }

    /// @notice deposit from Distributor (payable). Only distributor address can call.
    function depositFromDistributor() external payable whenNotPaused nonReentrant {
        if (msg.sender != distributor) revert NotDistributor();
        if (msg.value == 0) revert ZeroAmount();
        poolBalance += msg.value;
        emit DepositedFromDistributor(msg.sender, msg.value);
    }

    /// @notice compatibility: called by Distributor via selector receiveMintShare()
    function receiveMintShare() external payable whenNotPaused nonReentrant {
        if (msg.sender != distributor) revert NotDistributor();
        if (msg.value == 0) revert ZeroAmount();
        poolBalance += msg.value;
        emit DepositedFromDistributor(msg.sender, msg.value);
    }

    /// @notice owner can also top up pool manually
    function ownerDeposit() external payable onlyOwner whenNotPaused nonReentrant {
        if (msg.value == 0) revert ZeroAmount();
        poolBalance += msg.value;
        emit OwnerDeposit(msg.sender, msg.value);
    }

    /* ------------ Events management (owner) ------------ */

    function createEvent(
        string calldata title,
        string calldata ipfsHash,
        uint256 start,
        uint256 end,
        uint256 totalPrize,
        address[] calldata winners,
        uint256[] calldata amounts
    ) external onlyOwner whenNotPaused returns (uint256 eventId) {
        if (winners.length == 0 || winners.length != amounts.length) revert BadLengths();
        if (totalPrize == 0) revert ZeroAmount();

        // sum amounts
        uint256 s = 0;
        for (uint256 i = 0; i < amounts.length; ++i) {
            s += amounts[i];
        }
        if (s != totalPrize) revert SumMismatch();
        if (totalPrize > poolBalance) revert InsufficientPool();

        // reserve pool
        poolBalance -= totalPrize;
        totalLocked += totalPrize;

        eventId = nextEventId++;
        EventInfo storage e = events[eventId];
        e.title = title;
        e.ipfsHash = ipfsHash;
        e.start = start;
        e.end = end;
        e.totalPrize = totalPrize;
        e.locked = totalPrize;
        e.exists = true;

        // store winners + amounts
        for (uint256 i = 0; i < winners.length; ++i) {
            address w = winners[i];
            uint256 a = amounts[i];

            if (w == address(0)) revert ZeroAddress();
            if (a == 0) revert ZeroAmount();

            // prevent duplicates (otherwise mapping overwrite would cause silent inconsistency)
            if (eventAmounts[eventId][w] != 0) revert DuplicateWinner();

            eventWinners[eventId].push(w);
            eventAmounts[eventId][w] = a;

            emit WinnerAssigned(eventId, w, a);
        }

        allEventIds.push(eventId);
        emit EventCreated(eventId, title, totalPrize);
    }

    /* ------------ Claim (recipient withdraw) ------------ */

    /// @notice winner claims their amount for a given eventId
    function claim(uint256 eventId) external nonReentrant whenNotPaused {
        if (!events[eventId].exists) revert EventNotExists();

        uint256 amount = eventAmounts[eventId][msg.sender];
        if (amount == 0) revert NotWinner();
        if (eventClaimed[eventId][msg.sender]) revert AlreadyClaimed();

        // checks-effects-interactions
        eventClaimed[eventId][msg.sender] = true;

        EventInfo storage e = events[eventId];
        // sanity
        if (e.locked < amount) revert SumMismatch();

        e.locked -= amount;
        totalLocked -= amount;

        (bool ok, ) = payable(msg.sender).call{value: amount}("");
        if (!ok) revert TransferFailed();

        emit Claimed(eventId, msg.sender, amount);
    }

    /* ------------ Getters for frontend / indexers ------------ */

    /// @notice list of event ids (useful for FE)
    function getEvents() external view returns (uint256[] memory) {
        return allEventIds;
    }

    /// @notice basic event data
    function getEvent(uint256 eventId)
        external
        view
        returns (
            string memory title,
            string memory ipfsHash,
            uint256 start,
            uint256 end,
            uint256 totalPrize_,
            uint256 locked,
            bool exists
        )
    {
        EventInfo storage e = events[eventId];
        return (e.title, e.ipfsHash, e.start, e.end, e.totalPrize, e.locked, e.exists);
    }

    /// @notice winners + amounts + claimed flags
    function getEventWinners(uint256 eventId)
        external
        view
        returns (address[] memory winners, uint256[] memory amounts, bool[] memory claimed)
    {
        winners = eventWinners[eventId];
        amounts = new uint256[](winners.length);
        claimed = new bool[](winners.length);

        for (uint256 i = 0; i < winners.length; ++i) {
            address w = winners[i];
            amounts[i] = eventAmounts[eventId][w];
            claimed[i] = eventClaimed[eventId][w];
        }
    }

    /// @notice how much is locked for an event
    function balanceOfEvent(uint256 eventId) external view returns (uint256) {
        return events[eventId].locked;
    }

    /// @notice check payout assigned to an address (0 if none)
    function assignedAmountOf(uint256 eventId, address who) external view returns (uint256) {
        return eventAmounts[eventId][who];
    }

    /// @notice FE helper: user status for a given event
    function userStatus(uint256 eventId, address who) external view returns (uint256 amount, bool claimed, bool exists) {
        exists = events[eventId].exists;
        amount = eventAmounts[eventId][who];
        claimed = eventClaimed[eventId][who];
    }

    /// @notice FE helper: canClaim with reason codes
    /// reason: 0=OK, 1=EventNotExists, 2=NotWinner, 3=AlreadyClaimed, 4=Paused
    function canClaim(uint256 eventId, address who) external view returns (bool ok, uint8 reason, uint256 amount) {
        if (paused()) return (false, 4, 0);
        if (!events[eventId].exists) return (false, 1, 0);

        amount = eventAmounts[eventId][who];
        if (amount == 0) return (false, 2, 0);
        if (eventClaimed[eventId][who]) return (false, 3, amount);

        return (true, 0, amount);
    }

    /* ------------ Rescue / Admin helpers ------------ */

    /// @notice owner may rescue leftover pool funds (non-locked). Locked funds per event remain.
    function rescuePool(address payable to, uint256 amount) external onlyOwner whenNotPaused nonReentrant {
        if (to == address(0)) revert ZeroAddress();
        if (amount > poolBalance) revert InsufficientPool();
        poolBalance -= amount;
        to.sendValue(amount);
        emit Rescue(to, amount);
    }

    /// @notice emergency withdraw (owner) - sends entire contract balance that is not locked by events
    function emergencyWithdraw(address payable to) external onlyOwner whenPaused nonReentrant {
        if (to == address(0)) revert ZeroAddress();

        uint256 contractBal = address(this).balance;
        uint256 avail = contractBal > totalLocked ? (contractBal - totalLocked) : 0;
        require(avail > 0, "no avail");

        // keep poolBalance consistent: emergency withdraw should reduce free pool first
        if (avail >= poolBalance) {
            poolBalance = 0;
        } else {
            poolBalance -= avail;
        }

        to.sendValue(avail);
        emit Rescue(to, avail);
    }

    /* ------------ Pause / Unpause ------------ */
    function pause() external onlyOwner { _pause(); }
    function unpause() external onlyOwner { _unpause(); }

    /* ------------ Fallbacks ------------ */
    receive() external payable {
        if (msg.value == 0) return;

        poolBalance += msg.value;

        if (msg.sender == owner()) {
            emit OwnerDeposit(msg.sender, msg.value);
        } else if (msg.sender == distributor) {
            emit DepositedFromDistributor(msg.sender, msg.value);
        } else {
            emit DonationReceived(msg.sender, msg.value);
        }
    }
}

