    error CapExceeded();          // DripDistributor CAP (200M BIGGI) překročen
    error NotWhitelistedCollection(); // notifyMint volá ne-whitelisted kolekce
    error OnlyToken();                // funkci smí volat jen samotný BIGGI token kontrakt

    /* ========= Runtime / flow chyby ========= */
