pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable2Step.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/* ===== Orchestrator interface (minimal) ===== */
interface ILiquidityOrchestrator {
    function triggerPairing(uint256 requestedPol) external;
}

/* ===== Reserve interface (view only for sizing) ===== */
interface IReserveForKeeper {
    function polBalance() external view returns (uint256);
    function dexRefillBiggi() external view returns (uint256);
}

/**
 * @title BiggiLiquidityKeeperProxy
 * @dev KeeperProxy nad BiggiLiquidityOrchestrator.
 *      - Chainlink Automation kompatibilní: checkUpkeep / performUpkeep
 *      - Strategy pro amount: FIXED nebo PCT z reserve balance
 *      - Další lokální limity: minInterval, minReservePol, maxPerTx, minDexRefillBiggi
 *
+ * Pozn.: Orchestrator má vlastní pravidla (cooldown/quota/limity). KeeperProxy je nadstavba
 *        pro automatizaci a sizing amountu.
 */
contract BiggiLiquidityKeeperProxy is Ownable2Step, ReentrancyGuard, Pausable {
    error ZeroAddress();
    error NotAllowedCaller();
    error NoWork();
    error BadConfig();

    enum AmountMode {
        FIXED,      // vždy fixedAmount
        PCT_RESERVE // percentBps z reserve.polBalance()
    }

    ILiquidityOrchestrator public orchestrator;
    IReserveForKeeper public reserve;

    // Allowlist volajícího (např. Chainlink registry / executor)
    // Pokud nechceš řešit allowlist, nech "allowedCaller = address(0)" => povoleno komukoli.
    address public allowedCaller;

    // Sizing
    AmountMode public amountMode = AmountMode.PCT_RESERVE;
    uint256 public fixedAmount = 1 ether;     // když FIXED
    uint256 public percentBps = 500;          // 5.00% když PCT_RESERVE (BPS: 10000 = 100%)

    // Local safety limits (navíc k orchestrátoru)
    uint256 public minIntervalSec = 900;      // 15 min
    uint256 public lastPerformTs;

    uint256 public minReservePol = 1 ether; // minimální POL v reserve pro spuštění
    uint256 public maxPerTx = 20 ether;       // horní limit amountu z keeper proxy
    uint256 public minDexRefillBiggi = 1e18;  // minimální BIGGI v DEX_REFILL bucketu pro spuštění

    event OrchestratorSet(address indexed oldO, address indexed newO);
    event ReserveSet(address indexed oldR, address indexed newR);
    event AllowedCallerSet(address indexed oldA, address indexed newA);

    event StrategySet(AmountMode mode, uint256 fixedAmount, uint256 percentBps);
    event LimitsSet(
        uint256 minIntervalSec,
        uint256 minReservePol,
        uint256 maxPerTx,
        uint256 minDexRefillBiggi
    );

    event Performed(address indexed caller, uint256 amount);

    // DŮLEŽITÉ: base Ownable(owner_) kvůli OZ verzi, která chce initialOwner v Ownable constructoru
    constructor(address orchestrator_, address reserve_, address owner_) Ownable(owner_) {
        if (orchestrator_ == address(0) || reserve_ == address(0) || owner_ == address(0)) revert ZeroAddress();
        orchestrator = ILiquidityOrchestrator(orchestrator_);
        reserve = IReserveForKeeper(reserve_);
    }

    /* ===================== Admin ===================== */

    function setOrchestrator(address o) external onlyOwner {
        if (o == address(0)) revert ZeroAddress();
        emit OrchestratorSet(address(orchestrator), o);
        orchestrator = ILiquidityOrchestrator(o);
    }

    function setReserve(address r) external onlyOwner {
        if (r == address(0)) revert ZeroAddress();
        emit ReserveSet(address(reserve), r);
        reserve = IReserveForKeeper(r);
    }

    /// @notice Pokud nastavíš allowedCaller != 0, pouze tato adresa smí volat performUpkeep.
    ///        Pokud je allowedCaller = 0, performUpkeep může volat kdokoli.
    function setAllowedCaller(address a) external onlyOwner {
        emit AllowedCallerSet(allowedCaller, a);
        allowedCaller = a;
    }

    function setStrategy(AmountMode mode, uint256 fixedAmount_, uint256 percentBps_) external onlyOwner {
        if (mode == AmountMode.FIXED) {
            require(fixedAmount_ > 0, "fixed=0");
        } else {
            require(percentBps_ > 0 && percentBps_ <= 10_000, "bad bps");
        }
        amountMode = mode;
        fixedAmount = fixedAmount_;
        percentBps = percentBps_;
        emit StrategySet(mode, fixedAmount_, percentBps_);
    }

    function setLimits(
        uint256 minIntervalSec_,
        uint256 minReservePol_,
        uint256 maxPerTx_,
        uint256 minDexRefillBiggi_
    ) external onlyOwner {
        if (minIntervalSec_ > 7 days) revert BadConfig();
        if (maxPerTx_ == 0) revert BadConfig();

        minIntervalSec = minIntervalSec_;
        minReservePol = minReservePol_;
        maxPerTx = maxPerTx_;
        minDexRefillBiggi = minDexRefillBiggi_;

        emit LimitsSet(minIntervalSec_, minReservePol_, maxPerTx_, minDexRefillBiggi_);
    }

    function pauseAll() external onlyOwner { _pause(); }
    function unpauseAll() external onlyOwner { _unpause(); }

    /* ===================== Chainlink Automation ===================== */

    function checkUpkeep(bytes calldata)
        external
        view
        returns (bool upkeepNeeded, bytes memory performData)
    {
        if (paused()) return (false, bytes("paused"));

        if (block.timestamp < lastPerformTs + minIntervalSec) {
            return (false, bytes("interval"));
        }

        uint256 pol = reserve.polBalance();
        if (pol < minReservePol) {
            return (false, bytes("reserve pol low"));
        }

        uint256 biggiBucket = reserve.dexRefillBiggi();
        if (biggiBucket < minDexRefillBiggi) {
            return (false, bytes("reserve biggi bucket low"));
        }

        uint256 amount = _computeAmount(pol);
        if (amount == 0) {
            return (false, bytes("amount=0"));
        }

        return (true, abi.encode(amount));
    }

    function performUpkeep(bytes calldata performData)
        external
        nonReentrant
        whenNotPaused
    {
        if (allowedCaller != address(0) && msg.sender != allowedCaller) revert NotAllowedCaller();

        if (block.timestamp < lastPerformTs + minIntervalSec) revert NoWork();

        uint256 pol = reserve.polBalance();
        if (pol < minReservePol) revert NoWork();

        uint256 biggiBucket = reserve.dexRefillBiggi();
        if (biggiBucket < minDexRefillBiggi) revert NoWork();

        uint256 amount;
        if (performData.length == 32) {
            amount = abi.decode(performData, (uint256));
        } else {
            amount = _computeAmount(pol);
        }

        if (amount > maxPerTx) amount = maxPerTx;
        if (amount > pol) amount = pol;

        if (amount == 0) revert NoWork();

        lastPerformTs = block.timestamp;

        orchestrator.triggerPairing(amount);

        emit Performed(msg.sender, amount);
    }

    /* ===================== Admin manual trigger ===================== */

    function adminTrigger(uint256 amount) external onlyOwner nonReentrant whenNotPaused {
        require(amount > 0, "amount=0");
        lastPerformTs = block.timestamp;
        orchestrator.triggerPairing(amount);
        emit Performed(msg.sender, amount);
    }

    /* ===================== Views ===================== */

    function computedAmountNow() external view returns (uint256 amount, uint256 reservePol) {
        reservePol = reserve.polBalance();
        amount = _computeAmount(reservePol);
        if (amount > maxPerTx) amount = maxPerTx;
        if (amount > reservePol) amount = reservePol;
    }

    /* ===================== Internal ===================== */

    function _computeAmount(uint256 reservePolBal) internal view returns (uint256 amount) {
        if (amountMode == AmountMode.FIXED) {
            amount = fixedAmount;
        } else {
            amount = (reservePolBal * percentBps) / 10_000;
        }
        if (amount > maxPerTx) amount = maxPerTx;
        if (amount > reservePolBal) amount = reservePolBal;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

interface IUniswapV2Router02 {
    function WETH() external view returns (address);

    function getAmountsOut(uint amountIn, address[] calldata path)
        external
        view
        returns (uint[] memory amounts);

    function addLiquidityETH(
        address token,
        uint amountTokenDesired,
        uint amountTokenMin,
        uint amountETHMin,
        address to,
        uint deadline
    ) external payable returns (uint amountToken, uint amountETH, uint liquidity);
}

interface IUniswapV2Factory {
    function getPair(address tokenA, address tokenB) external view returns (address pair);
}

interface ILiquidityVault {
    function syncPairBalance(address lpPair) external;
}

interface IReserveV4 {
    function lmPullBiggiDexRefill(address to, uint256 amount) external;
    function lmPullPolDexRefill(address payable to, uint256 amount) external;
}

contract BiggiLiquidityManager is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    IERC20 public immutable BIGGI;

    IUniswapV2Router02 public router;
    IUniswapV2Factory public factory;

    address public reserve;
    address public liquidityVault;

    address public keeper;

    uint8   public tokenPct       = 50;
    uint256 public slippageBps    = 200;
    uint256 public txDeadlineSec  = 600;
    bool    public autoTopUpEnabled     = true;
    uint256 public autoTriggerMinPolWei = 5 ether; // spouštět pairing při >= 5 POL v Reserve
    uint256 public autoRequestPolWei    = 5 ether; // kolik POL se má žádat při auto párování

    event RouterSet(address indexed oldR, address indexed newR);
    event FactorySet(address indexed oldF, address indexed newF);
    event ReserveSet(address indexed oldR, address indexed newR);
    event LiquidityVaultSet(address indexed oldV, address indexed newV);
    event KeeperSet(address indexed oldK, address indexed newK);
    event TokenPctSet(uint8 oldPct, uint8 newPct);
    event SlippageSet(uint256 oldBps, uint256 newBps);
    event DeadlineSet(uint256 oldSec, uint256 newSec);

    event LiquidityAdded(uint256 nativeUsed, uint256 tokenUsed, uint256 liquidity);
    event LiquidityAddFailed(string reason);
    event ReserveTopUpRequested(address indexed reserve);
    event AutoTopUpConfigSet(bool enabled, uint256 triggerMinPolWei, uint256 requestPolWei);
    event AutoPairingAttempt(uint256 requestedPol, bool executed, string reason);

    modifier onlyOwnerOrKeeper() {
        require(msg.sender == owner() || msg.sender == keeper, "only owner/keeper");
        _;
    }

    modifier onlyReserve() {
        require(msg.sender == reserve, "only reserve");
        _;
    }

    constructor(
        address token_,
        address router_,
        address liquidityVault_,
        address initialOwner,
        address reserve_
    ) Ownable(initialOwner) {
        require(token_ != address(0), "token0");
        require(router_ != address(0), "router0");
        require(liquidityVault_ != address(0), "vault0");
        require(initialOwner != address(0), "owner0");
        require(reserve_ != address(0), "reserve0");

        BIGGI = IERC20(token_);
        router = IUniswapV2Router02(router_);
        liquidityVault = liquidityVault_;
        reserve = reserve_;
    }

    /* ============ owner setters ============ */

    function setRouter(address r) external onlyOwner {
        require(r != address(0), "zero");
        emit RouterSet(address(router), r);
        router = IUniswapV2Router02(r);
    }

    function setFactory(address f) external onlyOwner {
        require(f != address(0), "zero");
        emit FactorySet(address(factory), f);
        factory = IUniswapV2Factory(f);
    }

    function setReserve(address r) external onlyOwner {
        require(r != address(0), "zero");
        emit ReserveSet(reserve, r);
        reserve = r;
    }

    function setLiquidityVault(address v) external onlyOwner {
        require(v != address(0), "zero");
        emit LiquidityVaultSet(liquidityVault, v);
        liquidityVault = v;
    }

    function setKeeper(address k) external onlyOwner {
        emit KeeperSet(keeper, k);
        keeper = k;
    }

    function setTokenPct(uint8 pct) external onlyOwner {
        require(pct <= 100, "pct>100");
        emit TokenPctSet(tokenPct, pct);
        tokenPct = pct;
    }

    function setSlippageBps(uint256 bps) external onlyOwner {
        require(bps <= 10_000, "bps>10000");
        emit SlippageSet(slippageBps, bps);
        slippageBps = bps;
    }

    function setTxDeadlineSec(uint256 sec_) external onlyOwner {
        require(sec_ > 0 && sec_ <= 1 days, "bad-deadline");
        emit DeadlineSet(txDeadlineSec, sec_);
        txDeadlineSec = sec_;
    }

    function setAutoTopUpConfig(
        bool enabled,
        uint256 triggerMinPolWei,
        uint256 requestPolWei
    ) external onlyOwner {
        require(triggerMinPolWei > 0, "trigger=0");
        require(requestPolWei > 0, "request=0");
        autoTopUpEnabled = enabled;
        autoTriggerMinPolWei = triggerMinPolWei;
        autoRequestPolWei = requestPolWei;
        emit AutoTopUpConfigSet(enabled, triggerMinPolWei, requestPolWei);
    }

    /* ============ Reserve trigger hook ============ */

    /// @notice Called by Reserve when someone requests LM action (e.g., via Reserve.requestTopUpToLM)
    /// @dev Auto-spustí pairing pokud je povoleno a Reserve drží dost POL.
    function onReserveTopUpRequest() external onlyReserve {
        emit ReserveTopUpRequested(msg.sender);
        _autoPairIfReady();
    }

    function _autoPairIfReady() internal {
        if (!autoTopUpEnabled) {
            emit AutoPairingAttempt(0, false, "auto: disabled");
            return;
        }
        if (reserve == address(0)) return;

        uint256 availablePol = address(reserve).balance;
        if (availablePol < autoTriggerMinPolWei) return;

        uint256 requestedPol = autoRequestPolWei == 0 ? autoTriggerMinPolWei : autoRequestPolWei;
        if (requestedPol > availablePol) requestedPol = availablePol;
        if (requestedPol == 0) return;

        if (address(router) == address(0) || liquidityVault == address(0)) {
            emit AutoPairingAttempt(requestedPol, false, "auto: wiring not set");
            return;
        }

        // external call so we can catch reverts
        try this.executePairingFromReserve(requestedPol) {
            emit AutoPairingAttempt(requestedPol, true, "");
        } catch Error(string memory reason) {
            emit AutoPairingAttempt(requestedPol, false, reason);
        } catch {
            emit AutoPairingAttempt(requestedPol, false, "auto: revert");
        }
    }

    /* ============ Core: executePairing ============ */

    function executePairing(uint256 requestedPol) external nonReentrant onlyOwnerOrKeeper {
        _executePairing(requestedPol);
    }

    function executePairingFromReserve(uint256 requestedPol) external nonReentrant {
        require(msg.sender == reserve || msg.sender == address(this), "only reserve/self");
        _executePairing(requestedPol);
    }

    /* ============ Internals (split to avoid stack-too-deep) ============ */

    function _executePairing(uint256 requestedPol) internal {
        require(requestedPol > 0, "native==0");
        require(address(router) != address(0), "router not set");
        require(liquidityVault != address(0), "vault not set");
        require(reserve != address(0), "reserve not set");

        // 1) quote => tokenDesired
        (uint256 tokenDesired, address weth) = _quoteTokenDesired(requestedPol);
        if (tokenDesired == 0) return; // _quoteTokenDesired už emitne error

        // 2) pull BIGGI
        try IReserveV4(reserve).lmPullBiggiDexRefill(address(this), tokenDesired) {
        } catch {
            emit LiquidityAddFailed("reserve pull tokens failed");
            return;
        }

        // 3) pull POL
        try IReserveV4(reserve).lmPullPolDexRefill(payable(address(this)), requestedPol) {
        } catch {
            uint256 balTok = BIGGI.balanceOf(address(this));
            if (balTok > 0) BIGGI.safeTransfer(reserve, balTok);
            emit LiquidityAddFailed("reserve pull POL failed");
            return;
        }

        // 4) addLiquidity + refund leftovers + sync
        _addLiquidityAndFinalize(requestedPol, tokenDesired, weth);
    }

    function _quoteTokenDesired(uint256 requestedPol) internal returns (uint256 tokenDesired, address weth) {
        weth = router.WETH();

        address[] memory path = new address[](2);
        path[0] = weth;
        path[1] = address(BIGGI);

        bytes memory payload =
            abi.encodeWithSelector(IUniswapV2Router02.getAmountsOut.selector, requestedPol, path);

        (bool ok, bytes memory ret) = address(router).call(payload);
        if (!ok) {
            emit LiquidityAddFailed("quote failed");
            return (0, weth);
        }

        uint[] memory amounts;
        try this._decodeUintArray(ret) returns (uint[] memory decoded) {
            amounts = decoded;
        } catch {
            emit LiquidityAddFailed("quote decode failed");
            return (0, weth);
        }

        if (amounts.length == 0) {
            emit LiquidityAddFailed("quote returned 0");
            return (0, weth);
        }

        uint256 expectedBiggi = amounts[amounts.length - 1];
        if (expectedBiggi == 0) {
            emit LiquidityAddFailed("expectedBiggi==0");
            return (0, weth);
        }

        tokenDesired = (expectedBiggi * uint256(tokenPct)) / 100;
        if (tokenDesired == 0) {
            emit LiquidityAddFailed("tokenDesired==0");
            return (0, weth);
        }
    }

    function _addLiquidityAndFinalize(uint256 requestedPol, uint256 tokenDesired, address weth) internal {
        // approve router
        BIGGI.approve(address(router), 0);
        BIGGI.approve(address(router), tokenDesired);

        uint256 amountTokenMin = (tokenDesired * (10_000 - slippageBps)) / 10_000;
        uint256 amountETHMin   = (requestedPol * (10_000 - slippageBps)) / 10_000;
        uint256 deadline = block.timestamp + txDeadlineSec;

        try router.addLiquidityETH{value: requestedPol}(
            address(BIGGI),
            tokenDesired,
            amountTokenMin,
            amountETHMin,
            liquidityVault,
            deadline
        ) returns (uint amountTokenUsed, uint amountETHUsed, uint liquidity) {
            BIGGI.approve(address(router), 0);

            uint256 leftoverTok = BIGGI.balanceOf(address(this));
            if (leftoverTok > 0) BIGGI.safeTransfer(reserve, leftoverTok);

            uint256 leftoverNative = address(this).balance;
            if (leftoverNative > 0) {
                (bool okSend, ) = payable(reserve).call{value: leftoverNative}("");
                require(okSend, "native refund to reserve failed");
            }

            emit LiquidityAdded(amountETHUsed, amountTokenUsed, liquidity);
            _syncVaultAccounting(weth);
        } catch {
            BIGGI.approve(address(router), 0);

            uint256 balTok = BIGGI.balanceOf(address(this));
            if (balTok > 0) BIGGI.safeTransfer(reserve, balTok);

            uint256 balNative = address(this).balance;
            if (balNative > 0) {
                (bool okSend, ) = payable(reserve).call{value: balNative}("");
                require(okSend, "native refund to reserve failed");
            }

            emit LiquidityAddFailed("addLiquidity failed");
        }
    }

    function _syncVaultAccounting(address weth) private {
        if (address(factory) == address(0) || liquidityVault == address(0)) return;

        try factory.getPair(address(BIGGI), weth) returns (address pair) {
            if (pair != address(0)) {
                try ILiquidityVault(liquidityVault).syncPairBalance(pair) {
                } catch {
                }
            }
        } catch {
        }
    }

    // helper for try/catch decode
    function _decodeUintArray(bytes memory b) external pure returns (uint[] memory) {
        return abi.decode(b, (uint[]));
    }

    receive() external payable {}
    fallback() external payable {}
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable2Step.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/* ===== Minimal view/exec interfaces ===== */

interface IBiggiReserveOrch {
    function polBalance() external view returns (uint256);
    function dexRefillBiggi() external view returns (uint256);
    function requestTopUpToLM() external;
    function liquidityManager() external view returns (address);
}

interface IBiggiLiquidityManagerOrch {
    function executePairing(uint256 requestedPol) external;

    function tokenPct() external view returns (uint8);
    function slippageBps() external view returns (uint256);
    function txDeadlineSec() external view returns (uint256);
    function keeper() external view returns (address);

    function reserve() external view returns (address);
    function liquidityVault() external view returns (address);
    function router() external view returns (address);
}

interface ILiquidityVaultOrch {
    function liquidityManager() external view returns (address);
}

contract BiggiLiquidityOrchestrator is Ownable2Step, ReentrancyGuard, Pausable {
    error ZeroAddress();
    error OnlyOwnerOrKeeper();
    error Cooldown();
    error DailyQuotaExceeded();
    error RequestedZero();
    error BelowMinPerTx();
    error AboveMaxPerTx();
    error ReservePolLow();
    error ReserveBiggiLow();
    error WiringMismatch();

    IBiggiReserveOrch public reserve;
    IBiggiLiquidityManagerOrch public lm;

    address public keeper;

    uint256 public minPolPerTx = 0.5 ether;
    uint256 public maxPolPerTx = 50 ether;
    uint256 public minDexRefillBiggi = 1e18;
    uint256 public cooldownSec = 3600;
    uint256 public dailyQuotaPol = 0;

    uint256 public lastRunTimestamp;
    uint256 public usedToday;
    uint256 public dayMarker;

    event KeeperSet(address indexed oldK, address indexed newK);
    event ReserveSet(address indexed oldR, address indexed newR);
    event LMSet(address indexed oldLM, address indexed newLM);

    event LimitsUpdated(
        uint256 minPolPerTx,
        uint256 maxPolPerTx,
        uint256 minDexRefillBiggi,
        uint256 cooldownSec,
        uint256 dailyQuotaPol
    );

    event PairingTriggered(address indexed by, uint256 requestedPol);
    event ReserveTopUpRequested(address indexed by);

    modifier onlyOwnerOrKeeper() {
        if (msg.sender != owner() && msg.sender != keeper) revert OnlyOwnerOrKeeper();
        _;
    }

    // OZ v5: Ownable má constructor(address initialOwner)
    constructor(address reserve_, address lm_, address owner_)
        Ownable(owner_)
    {
        if (reserve_ == address(0) || lm_ == address(0) || owner_ == address(0)) revert ZeroAddress();
        reserve = IBiggiReserveOrch(reserve_);
        lm = IBiggiLiquidityManagerOrch(lm_);
        dayMarker = block.timestamp / 1 days;
    }

    /* ===================== Admin wiring ===================== */

    function setKeeper(address k) external onlyOwner {
        emit KeeperSet(keeper, k);
        keeper = k;
    }

    function setReserve(address r) external onlyOwner {
        if (r == address(0)) revert ZeroAddress();
        emit ReserveSet(address(reserve), r);
        reserve = IBiggiReserveOrch(r);
    }

    function setLM(address l) external onlyOwner {
        if (l == address(0)) revert ZeroAddress();
        emit LMSet(address(lm), l);
        lm = IBiggiLiquidityManagerOrch(l);
    }

    /* ===================== Admin params ===================== */

    function setLimits(
        uint256 minPolPerTx_,
        uint256 maxPolPerTx_,
        uint256 minDexRefillBiggi_,
        uint256 cooldownSec_,
        uint256 dailyQuotaPol_
    ) external onlyOwner {
        require(minPolPerTx_ <= maxPolPerTx_, "min>max");
        require(cooldownSec_ <= 7 days, "cooldown too big");

        minPolPerTx = minPolPerTx_;
        maxPolPerTx = maxPolPerTx_;
        minDexRefillBiggi = minDexRefillBiggi_;
        cooldownSec = cooldownSec_;
        dailyQuotaPol = dailyQuotaPol_;

        emit LimitsUpdated(minPolPerTx, maxPolPerTx, minDexRefillBiggi, cooldownSec, dailyQuotaPol);
    }

    function pauseAll() external onlyOwner { _pause(); }
    function unpauseAll() external onlyOwner { _unpause(); }

    /* ===================== Core orchestration ===================== */

    function triggerPairing(uint256 requestedPol)
        external
        nonReentrant
        whenNotPaused
        onlyOwnerOrKeeper
    {
        if (requestedPol == 0) revert RequestedZero();
        if (requestedPol < minPolPerTx) revert BelowMinPerTx();
        if (requestedPol > maxPolPerTx) revert AboveMaxPerTx();

        if (reserve.liquidityManager() != address(lm)) revert WiringMismatch();
        if (lm.reserve() != address(reserve)) revert WiringMismatch();
        address vault = lm.liquidityVault();
        if (vault == address(0)) revert WiringMismatch();
        if (ILiquidityVaultOrch(vault).liquidityManager() != address(lm)) revert WiringMismatch();

        if (block.timestamp < lastRunTimestamp + cooldownSec) revert Cooldown();

        _resetDayIfNeeded();
        if (dailyQuotaPol != 0 && usedToday + requestedPol > dailyQuotaPol) revert DailyQuotaExceeded();

        if (reserve.polBalance() < requestedPol) revert ReservePolLow();
        if (reserve.dexRefillBiggi() < minDexRefillBiggi) revert ReserveBiggiLow();

        usedToday += requestedPol;
        lastRunTimestamp = block.timestamp;

        lm.executePairing(requestedPol);

        emit PairingTriggered(msg.sender, requestedPol);
    }

    function requestReserveTopUp() external onlyOwnerOrKeeper whenNotPaused {
        reserve.requestTopUpToLM();
        emit ReserveTopUpRequested(msg.sender);
    }

    /* ===================== Views for Admin panel (split to avoid stack-too-deep) ===================== */

    function adminSnapshotCore() external view returns (
        // balances
        uint256 reservePol,
        uint256 reserveDexRefillBiggi,

        // orchestrator state
        uint256 _minPolPerTx,
        uint256 _maxPolPerTx,
        uint256 _minDexRefillBiggi,
        uint256 _cooldownSec,
        uint256 _dailyQuotaPol,
        uint256 _lastRun,
        uint256 _usedToday,
        uint256 _dayMarker,

        // wiring
        address reserveAddr,
        address lmAddr,
        address keeperAddr,
        bool wiredOk
    ) {
        reservePol = reserve.polBalance();
        reserveDexRefillBiggi = reserve.dexRefillBiggi();

        _minPolPerTx = minPolPerTx;
        _maxPolPerTx = maxPolPerTx;
        _minDexRefillBiggi = minDexRefillBiggi;
        _cooldownSec = cooldownSec;
        _dailyQuotaPol = dailyQuotaPol;
        _lastRun = lastRunTimestamp;
        _usedToday = usedToday;
        _dayMarker = dayMarker;

        reserveAddr = address(reserve);
        lmAddr = address(lm);
        keeperAddr = keeper;

        wiredOk = (reserve.liquidityManager() == address(lm)) && (lm.reserve() == address(reserve));
        if (wiredOk) {
            address vaultAddr = lm.liquidityVault();
            if (vaultAddr == address(0)) {
                wiredOk = false;
            } else {
                try ILiquidityVaultOrch(vaultAddr).liquidityManager() returns (address lmInVault) {
                    wiredOk = lmInVault == address(lm);
                } catch {
                    wiredOk = false;
                }
            }
        }
    }

    function adminSnapshotLM() external view returns (
        uint8 lmTokenPct,
        uint256 lmSlippageBps,
        uint256 lmDeadlineSec,
        address lmKeeper,
        address lmRouter,
        address lmVault,
        address lmReserve
    ) {
        lmTokenPct = lm.tokenPct();
        lmSlippageBps = lm.slippageBps();
        lmDeadlineSec = lm.txDeadlineSec();
        lmKeeper = lm.keeper();
        lmRouter = lm.router();
        lmVault = lm.liquidityVault();
        lmReserve = lm.reserve();
    }

    function _resetDayIfNeeded() internal {
        uint256 today = block.timestamp / 1 days;
        if (today != dayMarker) {
            dayMarker = today;
            usedToday = 0;
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

interface IFactory {
    function getPair(address tokenA, address tokenB) external view returns (address);
}

interface IRouter {
    function WETH() external view returns (address);
    function addLiquidityETH(
        address token,
        uint amountTokenDesired,
        uint amountTokenMin,
        uint amountETHMin,
        address to,
        uint deadline
    ) external payable returns (uint amountToken, uint amountETH, uint liquidity);
}

interface IBiggiTokenWithReserve is IERC20 {
    function transferFromReserveTo(address to, uint256 amount) external;
}

interface ILiquidityManager {
    function setRouter(address r) external;
    function setFactory(address f) external;
    function setReserve(address r) external;
    function setLiquidityVault(address v) external;
    function setKeeper(address k) external;
    function setTokenPct(uint8 pct) external;
    function setSlippageBps(uint256 bps) external;
    function setTxDeadlineSec(uint256 sec_) external;
    function setAutoTopUpConfig(bool enabled, uint256 triggerMinPolWei, uint256 requestPolWei) external;
}

interface IVault {
    function addWhitelistedPair(address lpPair) external;
    function whitelistPair(address pair, bool allowed) external;
}

interface IReserveSetup {
    function setLiquidityManager(address lm) external;
}

/**
 * @title LiquiditySetup
 * @notice Propojí Reserve / LiquidityManager / Vault a udělá initial liquidity (one-shot).
 *         Upraveno pro aktuální LM API (router/factory/reserve/vault/keeper/autoTopUp).
 */
contract LiquiditySetup is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    IBiggiTokenWithReserve public immutable BIGGI;
    IRouter public immutable router;
    address public immutable vault;
    address public immutable liquidityManager;
    address public immutable reserve;
    address public immutable wNative;

    uint256 public slippageBps = 300; // default 3 %
    uint256 public deadlineSec = 900; // 15 min

    bool public executedInitial;

    event InitialLiquidityAdded(uint256 amountTokenUsed, uint256 amountNativeUsed, uint256 liquidity);
    event ReserveLiquidityWired(address reserve, address lm, address vault);

    constructor(
        address initialOwner,
        address biggiToken_,
        address router_,
        address vault_,
        address liquidityManager_,
        address reserve_,
        address wNative_
    ) Ownable(initialOwner) {
        require(initialOwner != address(0), "owner=0");
        require(biggiToken_ != address(0), "token=0");
        require(router_ != address(0), "router=0");
        require(vault_ != address(0), "vault=0");
        require(liquidityManager_ != address(0), "lm=0");
        require(reserve_ != address(0), "reserve=0");
        require(wNative_ != address(0), "wnative=0");

        BIGGI = IBiggiTokenWithReserve(biggiToken_);
        router = IRouter(router_);
        vault = vault_;
        liquidityManager = liquidityManager_;
        reserve = reserve_;
        wNative = wNative_;
    }

    // --- admin tuning ---
    function setSlippageBps(uint256 newBps) external onlyOwner {
        require(newBps <= 1000, "slip>10%");
        slippageBps = newBps;
    }
    function setDeadlineSec(uint256 newDeadline) external onlyOwner {
        require(newDeadline > 0 && newDeadline <= 3600, "bad deadline");
        deadlineSec = newDeadline;
    }

    /// Propojí Reserve -> LM -> Vault a nastaví LM parametry (factory/keeper/tokenPct/slippage/deadline/autoTopUp).
    function setupReserveLMVault(
        address factory,
        address keeper,
        uint8 tokenPct,
        uint256 slippageBps_,
        uint256 deadlineSec_,
        bool autoEnabled,
        uint256 autoTriggerPolWei,
        uint256 autoRequestPolWei
    ) external onlyOwner {
        IReserveSetup(reserve).setLiquidityManager(liquidityManager);

        ILiquidityManager lm = ILiquidityManager(liquidityManager);
        lm.setRouter(address(router));
        if (factory != address(0)) lm.setFactory(factory);
        lm.setReserve(reserve);
        lm.setLiquidityVault(vault);
        if (keeper != address(0)) lm.setKeeper(keeper);
        lm.setTokenPct(tokenPct);
        lm.setSlippageBps(slippageBps_);
        lm.setTxDeadlineSec(deadlineSec_);
        lm.setAutoTopUpConfig(autoEnabled, autoTriggerPolWei, autoRequestPolWei);

        emit ReserveLiquidityWired(reserve, liquidityManager, vault);
    }

    /// Zjistí pair přes factory a whitelistne ho ve vaultu
    function runDexConnections(address factory) external onlyOwner {
        require(factory != address(0), "factory=0");
        address pair = IFactory(factory).getPair(address(BIGGI), wNative);
        require(pair != address(0), "pair not created yet");
        IVault(vault).addWhitelistedPair(pair);
    }

    /// One-shot initial liquidity: stáhne token z reserve a udělá addLiquidityETH do routeru (LP -> vault)
    /// Volat jako owner BiggiTokenu nebo after transferOwnership
    function runInitialLiquidity(uint256 tokenAmount) external payable nonReentrant onlyOwner {
        require(!executedInitial, "already executed");
        require(tokenAmount > 0, "tokenAmount=0");
        require(msg.value > 0, "need native");

        executedInitial = true;

        BIGGI.transferFromReserveTo(address(this), tokenAmount);

        IERC20 token = IERC20(address(BIGGI));

        // approve router
        uint256 curAllow = token.allowance(address(this), address(router));
        if (curAllow != 0) {
            require(token.approve(address(router), 0), "approve0");
        }
        require(token.approve(address(router), tokenAmount), "approve");

        uint256 tokenMin = (tokenAmount * (10_000 - slippageBps)) / 10_000;
        uint256 nativeMin = (msg.value * (10_000 - slippageBps)) / 10_000;
        uint256 dl = block.timestamp + deadlineSec;

        (uint256 usedToken, uint256 usedNative, uint256 liq) = router.addLiquidityETH{value: msg.value}(
            address(BIGGI),
            tokenAmount,
            tokenMin,
            nativeMin,
            vault,
            dl
        );

        emit InitialLiquidityAdded(usedToken, usedNative, liq);

        uint256 leftoverToken = token.balanceOf(address(this));
        if (leftoverToken > 0) {
            token.safeTransfer(owner(), leftoverToken);
        }
        uint256 leftoverNative = address(this).balance;
        if (leftoverNative > 0) {
            (bool ok, ) = payable(owner()).call{value: leftoverNative}("");
            require(ok, "refund failed");
        }

        token.approve(address(router), 0);
    }

    receive() external payable {}
}

